-- content_docs
INSERT INTO content_docs (key, data) VALUES ('about', $json${"title":"About SPEDICS","intro":"SPEDICS provides professionally structured training designed to develop practical knowledge, confidence and career-ready skills.","welcomeNote":{"title":"Welcome to SPEDICS","heading":"Empowering Educators. Enriching Childhood.","text":"SPEDICS Institute of Skill Development offers structured, practical and career-oriented teacher training and skill development programmes in Chennai. Whether you are a graduate, working teacher, homemaker or career changer — we help you build confidence and classroom-ready skills through online, offline and hybrid learning."},"whoWeAre":{"title":"Who We Are","text":"We are a Chennai-based institute focused on education and child development training. Our programmes combine structured curriculum, hands-on practice, trainer guidance and recognised certification — designed so learners can apply what they learn in real preschools, schools and education settings."},"founderMessage":{"title":"Message from the Founder","name":"SPEDICS Leadership","text":"Every child deserves a confident, skilled educator. At SPEDICS we believe training should be practical, accessible and rooted in real classroom experience. Our mission is to guide you from your first enquiry to a meaningful career in education — with flexible modes and ongoing support throughout your journey."},"vision":{"title":"Vision","text":"To empower educators and learners with practical skills to create better learning experiences and stronger futures."},"mission":{"title":"Mission","text":"To provide quality, practical and child-centred training that builds confident and competent professionals."},"whyChoose":[{"icon":"book","title":"Structured Curriculum","text":"Well-organised modules designed for progressive learning."},{"icon":"hands","title":"Practical Learning","text":"Hands-on activities, demonstrations and real classroom strategies."},{"icon":"devices","title":"Online & Offline","text":"Flexible modes to suit working professionals and homemakers."},{"icon":"clipboard","title":"Assessments","text":"Assignments and evaluations to track your progress."},{"icon":"users","title":"Trainer Guidance","text":"Experienced mentors supporting you throughout the journey."}],"montessori":{"title":"Why Montessori?","intro":"Montessori education encourages independence, hands-on learning and respect for each child's individual development.","points":["Builds independence and confidence","Encourages hands-on learning","Supports natural development","Develops concentration and coordination","Promotes a child-centred environment"]},"whoCanJoin":["Students and graduates","Existing teachers","Preschool educators","Homemakers","Parents","Career changers","Aspiring education professionals","Education entrepreneurs"]}$json$::jsonb);
INSERT INTO content_docs (key, data) VALUES ('admissions', $json${"title":"Admission Process","marquee":["Admissions Open for 2026–2027","Online · Offline · Hybrid modes available","Enquire via WhatsApp — quick counselling with our admissions team","Montessori · Child Psychology · Special Education · Language & more"],"steps":[{"step":1,"title":"Choose Your Course","text":"Browse our programmes and select the course that matches your goals."},{"step":2,"title":"Check Eligibility","text":"Review eligibility criteria on the course page or speak with our team."},{"step":3,"title":"Send Enquiry on WhatsApp","text":"Fill the form and tap Enquire via WhatsApp — your details are sent directly to our admissions team."},{"step":4,"title":"Speak with Admissions","text":"Our counsellor will guide you on mode, schedule and fee details."},{"step":5,"title":"Complete Formalities","text":"Submit documents and complete payment as advised."},{"step":6,"title":"Begin Training","text":"Start your learning journey with SPEDICS!"}],"formFields":[{"name":"fullName","label":"Full Name","type":"text","required":true},{"name":"mobile","label":"Mobile Number","type":"tel","required":true},{"name":"whatsapp","label":"WhatsApp Number","type":"tel","required":false},{"name":"email","label":"Email Address","type":"email","required":true},{"name":"qualification","label":"Highest Qualification","type":"text","required":true},{"name":"city","label":"City","type":"text","required":true},{"name":"course","label":"Course Interested","type":"select","required":true},{"name":"mode","label":"Preferred Mode","type":"select","options":["Online","Offline","Hybrid"],"required":true},{"name":"message","label":"Message","type":"textarea","required":false}],"courseFee":"Most courses: Certified ₹10,000 (3 months), Diploma ₹15,000 (6 months). Montessori also offers PG Diploma ₹35,000 (12 months). Spoken English/Hindi ₹3,000 (3 months, 3 classes/week). Phonics ₹5,000 (2 months, 2 classes/week). Tamil/Telugu ₹3,000 (3 months).","documentsRequired":"ID proof, educational certificates, passport-size photograph (details provided on application)"}$json$::jsonb);
