  'Are the courses available online?', 'Selected programmes can be offered online. Please check the individual course page or contact our admission team for current availability.', NULL, 0
);
INSERT INTO faq_items (question, answer, answer_with_fees, sort_order) VALUES (
  'Can working teachers join?', 'Yes, eligible working teachers can apply. Our flexible online and hybrid modes are designed to accommodate professional schedules.', NULL, 1
);
INSERT INTO faq_items (question, answer, answer_with_fees, sort_order) VALUES (
  'Can homemakers join?', 'Yes, eligible homemakers can apply. Many of our learners are parents and homemakers pursuing a meaningful career in education.', NULL, 2
);
INSERT INTO faq_items (question, answer, answer_with_fees, sort_order) VALUES (
  'Will I receive a certificate?', 'Learners who successfully complete the applicable programme requirements will receive the corresponding course certificate with affiliation details.', NULL, 3
);
INSERT INTO faq_items (question, answer, answer_with_fees, sort_order) VALUES (
  'Can I apply for a job after completing a course?', 'The course can support relevant job applications, but employment depends on the learner''s qualifications and the requirements of each school or employer.', NULL, 4
);
INSERT INTO faq_items (question, answer, answer_with_fees, sort_order) VALUES (
  'What documents are required for admission?', 'Typically ID proof, educational certificates and a passport-size photograph. Our team will guide you through the complete list during application.', NULL, 5
);
INSERT INTO faq_items (question, answer, answer_with_fees, sort_order) VALUES (
  'What is the course fee?', 'Contact us for fee details. Call or WhatsApp 7708743942 and our counsellor will share the current fee for your chosen course.', 'Most courses: Certified ₹10,000 for 3 months, Diploma ₹15,000 for 6 months. Montessori also has a PG Diploma at ₹35,000 for 12 months. Spoken English/Hindi ₹3,000 (3 months), Phonics ₹5,000 (2 months), Tamil/Telugu ₹3,000 (3 months). Call 7708743942 for instalment options.', 6
);
INSERT INTO faq_items (question, answer, answer_with_fees, sort_order) VALUES (
  'Where is SPEDICS located in Chennai?', 'SPEDICS Institute is at 4021, 6th Main Road, Ayapakkam, Chennai – 600077. We serve learners from Ayapakkam, Ambattur, Avadi, Padi, Mogappair and across Chennai with online and offline modes.', NULL, 7
);
INSERT INTO content_docs (key, data) VALUES ('faq-meta', $json${"title":"Frequently Asked Questions"}$json$::jsonb)
ON CONFLICT (key) DO UPDATE SET data = EXCLUDED.data;

