-- guides
INSERT INTO guides_meta (id, title, subtitle, item_ids) VALUES (1, 'Teacher Training Guides', 'Practical answers to common questions about choosing teacher training and skill development courses in Chennai.', $json$["how-to-choose-teacher-training-institute-chennai","best-montessori-teacher-training-chennai","teacher-training-near-ayapakkam-chennai"]$json$::jsonb);
INSERT INTO guides (id, title, meta_description, intro, sections, related_courses, related_guides, faqs, sort_order) VALUES (
  'how-to-choose-teacher-training-institute-chennai', 'How to Choose a Teacher Training Institute in Chennai', 'A practical checklist for choosing a teacher training institute in Chennai — accreditation, practical training, fees, modes, certificates and career support compared.', 'Choosing a teacher training institute in Chennai is not only about finding the nearest centre. The right programme should match your career goal, schedule, budget and the type of schools you want to work with. Use this checklist before you enrol.',
  $json$[{"heading":"What should you look for when choosing a teacher training institute?","type":"checklist","intro":"Compare institutes against these criteria before you pay any fee.","items":[{"criterion":"Affiliation and certificate recognition","detail":"Check whether certificates are issued with a recognised affiliation number and whether the institute can show proof of affiliation.","spedics":"We are affiliated with MMFRC (MARIA MONTESSORI FOUNDATION RESEARCH CENTRE). Our MMFRC Certification of Recognition is published on the website."},{"criterion":"Practical, classroom-focused training","detail":"Teacher training should include demonstrations, lesson planning practice and real classroom strategies — not only theory handouts.","spedics":"We emphasise practical learning with classroom demonstrations, Montessori materials, phonics workshops and guided teaching practice."},{"criterion":"Course duration and fee transparency","detail":"Ask for clear package options — certified vs diploma — with duration and total fee in writing.","spedics":"Most courses offer Certified (3 months, ₹10,000) and Diploma (6 months, ₹15,000). Montessori also includes a PG Diploma (12 months, ₹35,000). Fees are listed on the website."},{"criterion":"Online, offline and hybrid options","detail":"Working teachers and homemakers often need flexible modes. Confirm whether live classes, recordings and in-person sessions are available.","spedics":"We offer <strong class=\"guide-mode-highlight\">online</strong>, offline and hybrid modes across programmes."},{"criterion":"Eligibility and counselling","detail":"A good institute explains who can join, what documents are needed and which course fits your background.","spedics":"Admission counselling is available by phone/WhatsApp at 7708743942. Eligibility is listed on each course page."},{"criterion":"Location and accessibility","detail":"If you prefer offline classes, consider travel time, parking and whether the centre is reachable from your area.","spedics":"We are located at 4021, 6th Main Road, Ayapakkam, Chennai – 600077 — convenient for north Chennai areas including Ambattur, Avadi, Padi and Mogappair."},{"criterion":"Trainer guidance and assessments","detail":"Look for structured modules, assignments and mentor support — not just certificate issuance.","spedics":"Programmes include module-wise learning, assessments and trainer guidance throughout the course."}]},{"heading":"Who can enrol?","type":"list","items":["Graduates and 10+2 pass students entering education careers","Existing preschool and primary teachers upgrading skills","Homemakers and parents moving into education roles","Career changers interested in Montessori, special education or school administration","Aspiring entrepreneurs planning a preschool or training centre"]},{"heading":"Questions to ask before you enrol","type":"list","items":["What certificate will I receive and who is the affiliating body?","Is the fee all-inclusive or are there extra charges for materials or exams?","Can I attend online if I miss an offline session?","How many classes per week and what is the total duration?","Will I get help with job applications or school interviews?","Can I visit the institute and speak with the admissions team first?"]}]$json$::jsonb, $json$["montessori-teacher-training","child-psychology-development","special-education"]$json$::jsonb, $json$["best-montessori-teacher-training-chennai","teacher-training-near-ayapakkam-chennai"]$json$::jsonb, $json$[{"question":"What qualification do I need for teacher training in Chennai?","answer":"Most SPEDICS programmes require 10+2 or equivalent. Some advanced diplomas prefer graduates. Check the eligibility section on the specific course page."},{"question":"Are online teacher training certificates valid?","answer":"Validity depends on the affiliating body and the school employer. SPEDICS issues certificates with affiliation details for completed programmes. Always confirm requirements with your target employer."},{"question":"How much does teacher training cost in Chennai?","answer":"At SPEDICS, most courses are ₹10,000 (Certified, 3 months) or ₹15,000 (Diploma, 6 months). Language and phonics courses have separate fees listed on the website."}]$json$::jsonb, 0
);
INSERT INTO guides (id, title, meta_description, intro, sections, related_courses, related_guides, faqs, sort_order) VALUES (
  'best-montessori-teacher-training-chennai', 'Best Montessori Teacher Training in Chennai — What to Look For', 'How to evaluate Montessori teacher training programmes in Chennai: curriculum, practical life & sensorial modules, certification, fees and career outcomes.', 'Montessori teacher training prepares educators to work in child-centred preschool and primary environments. If you are searching for Montessori teacher training in Chennai, compare programmes on curriculum depth, hands-on practice and certificate recognition — not marketing claims alone.',
  $json$[{"heading":"What makes a strong Montessori teacher training programme?","type":"checklist","intro":"A credible Montessori course should cover philosophy and practical classroom application.","items":[{"criterion":"Montessori philosophy and child development","detail":"Training should explain Dr. Montessori's principles, sensitive periods and the role of the prepared environment.","spedics":"SPEDICS Montessori programme includes Montessori Philosophy & History and Child Development modules."},{"criterion":"Practical Life and Sensorial education","detail":"Look for demonstrations with real Montessori materials — not only slides.","spedics":"Modules cover Practical Life, Sensorial Education, Language and Mathematics with hands-on demonstrations."},{"criterion":"Lesson planning and classroom management","detail":"Teachers must learn observation, documentation and how to manage mixed-age classrooms.","spedics":"Course includes Lesson Planning, Classroom Management, Observation & Documentation and Teaching Practice."},{"criterion":"Flexible certification levels","detail":"Institutes should offer certified, diploma and advanced options with clear duration and fees.","spedics":"Certified (3 months, ₹10,000), Diploma (6 months, ₹15,000), PG Diploma (12 months, ₹35,000)."},{"criterion":"Affiliation and certificate details","detail":"Verify the affiliating organisation and whether the certificate number is traceable.","spedics":"Certificates are issued with MMFRC (MARIA MONTESSORI FOUNDATION RESEARCH CENTRE) affiliation (No. 2011/MMFRC/036)."}]},{"heading":"Montessori training packages at SPEDICS","type":"table","headers":["Package","Duration","Fee"],"rows":[["Certified","3 months","₹10,000"],["Diploma","6 months","₹15,000"],["PG Diploma","12 months","₹35,000"]]},{"heading":"Who should consider Montessori teacher training?","type":"list","items":["Aspiring preschool and kindergarten teachers","Parents planning to home-school with Montessori methods","Existing teachers moving into early childhood education","Entrepreneurs opening a Montessori preschool","Graduates seeking a structured education career in Chennai"]},{"heading":"Career paths after Montessori training","type":"text","content":"Montessori-trained educators commonly work in preschools, daycare centres, Montessori schools and as curriculum coordinators. Some graduates start their own pre-primary programmes. Employment depends on your overall qualifications and each school's hiring policy — the training supports your application but does not guarantee placement."}]$json$::jsonb, $json$["montessori-teacher-training"]$json$::jsonb, $json$["how-to-choose-teacher-training-institute-chennai","teacher-training-near-ayapakkam-chennai"]$json$::jsonb, $json$[{"question":"What is the fee for Montessori teacher training in Chennai at SPEDICS?","answer":"Certified: ₹10,000 (3 months). Diploma: ₹15,000 (6 months). PG Diploma: ₹35,000 (12 months)."},{"question":"Can I study Montessori training online in Chennai?","answer":"Yes. SPEDICS offers online, offline and hybrid modes for Montessori teacher training."},{"question":"Is SPEDICS Montessori training affiliated?","answer":"Yes. We are affiliated with MMFRC (MARIA MONTESSORI FOUNDATION RESEARCH CENTRE). Certification of Recognition details are available on the website."}]$json$::jsonb, 1
);
INSERT INTO guides (id, title, meta_description, intro, sections, related_courses, related_guides, faqs, sort_order) VALUES (
  'teacher-training-near-ayapakkam-chennai', 'Teacher Training Near Ayapakkam, Chennai', 'Teacher training institute near Ayapakkam, Chennai — SPEDICS offers Montessori, child psychology, special education and skill courses with online and offline modes.', 'If you live in or near Ayapakkam and are looking for a teacher training institute, location matters for offline classes, counselling visits and practical sessions. SPEDICS Institute of Skill Development is based in Ayapakkam and serves learners across north Chennai and surrounding areas.',
  $json$[{"heading":"SPEDICS location and areas served","type":"text","content":"SPEDICS is located at 4021, 6th Main Road, Ayapakkam, Chennai – 600077. The institute serves learners from Ayapakkam and nearby areas including Ambattur, Avadi, Padi, Mogappair, Thirumullaivoyal and Anna Nagar. Online and hybrid modes are available if you prefer learning from home."},{"heading":"Popular courses for local learners","type":"list","items":["Montessori Teacher Training — Certified, Diploma and PG Diploma","Child Psychology & Child Development","Special Education","Phonics & Early Literacy","Pre-Primary School Management","Spoken English and Spoken Hindi","Tamil and Telugu Reading & Writing"]},{"heading":"Why choose a local teacher training centre?","type":"checklist","intro":"Training near your area can make regular attendance and counselling easier.","items":[{"criterion":"Easy visit for admission counselling","detail":"Speaking in person helps you choose the right course and mode.","spedics":"Call or WhatsApp 7708743942 to schedule a visit or virtual counselling."},{"criterion":"Offline practical sessions","detail":"Classroom demonstrations and workshops are easier when the centre is nearby.","spedics":"We conduct practical classroom training, Montessori demos and workshop-style sessions."},{"criterion":"Flexible modes","detail":"Even with a local centre, online classes help working professionals.","spedics":"Choose <strong class=\"guide-mode-highlight\">online</strong>, offline or hybrid based on your schedule."},{"criterion":"Transparent fees","detail":"Local institutes should publish fee packages clearly.","spedics":"Most courses: ₹10,000 (3 months Certified) or ₹15,000 (6 months Diploma). Full fee list on the website."}]},{"heading":"Contact and visiting hours","type":"text","content":"Phone / WhatsApp: 7708743942 · Email: spedicsmont@gmail.com · Address: 4021, 6th Main Road, Ayapakkam, Chennai – 600077 · Office hours: Monday to Saturday, 9:00 AM – 6:00 PM."}]$json$::jsonb, $json$["montessori-teacher-training","phonics-early-literacy","child-psychology-development"]$json$::jsonb, $json$["how-to-choose-teacher-training-institute-chennai","best-montessori-teacher-training-chennai"]$json$::jsonb, $json$[{"question":"Is there a Montessori course near Ayapakkam?","answer":"Yes. SPEDICS in Ayapakkam offers Montessori Teacher Training with Certified, Diploma and PG Diploma options."},{"question":"Does SPEDICS offer online classes for Ayapakkam students?","answer":"Yes. Online and hybrid modes are available in addition to offline classes at the Ayapakkam centre."},{"question":"What is the address of SPEDICS in Chennai?","answer":"4021, 6th Main Road, Ayapakkam, Chennai – 600077."}]$json$::jsonb, 2
);

